import * as arc from "open-arc";

export interface Nested extends Array<number | null | undefined | Nested> {}

export type FlattenFn = (input: Nested) => number[];

export const flattenSpec = arc.defineRegion<FlattenFn>({
  "id": "flattenArray.flatten",
  "intent": [
    "Exercise \"flatten-array\": implement `flatten`.",
    "Take a nested array of any depth and return a fully flattened array.",
    "Note that some language tracks may include null-like values in the input array, and the way these values are represented varies by track. Such values should be excluded from the flattened array.",
    "Additionally, the input may be of a different data type and contain different types, depending on the track.",
    "Check the test suite for details.",
    "## Example",
    "input: `[1, [2, 6, null], [[null, [4]], 5]]`",
    "output: `[1, 2, 6, 4, 5]`"
  ],
  "examples": [
    {
      "name": "Flatten Array > no nesting",
      "args": [
        [
          0,
          1,
          2
        ]
      ],
      "expected": [
        0,
        1,
        2
      ]
    },
    {
      "name": "Flatten Array > flattens array with just integers present",
      "args": [
        [
          1,
          [
            2,
            3,
            4,
            5,
            6,
            7
          ],
          8
        ]
      ],
      "expected": [
        1,
        2,
        3,
        4,
        5,
        6,
        7,
        8
      ]
    },
    {
      "name": "Flatten Array > 5 level nesting",
      "args": [
        [
          0,
          2,
          [
            [
              2,
              3
            ],
            8,
            100,
            4,
            [
              [
                [
                  50
                ]
              ]
            ]
          ],
          -2
        ]
      ],
      "expected": [
        0,
        2,
        2,
        3,
        8,
        100,
        4,
        50,
        -2
      ]
    }
  ]
});

// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  const stack: (number | null | undefined | Nested)[] = [...input];
  while (stack.length > 0) {
      const item = stack.pop();
      if (item === null || item === undefined) {
        continue;
      }
      if (Array.isArray(item)) {
        stack.push(...item);
      } else {
        result.push(item);
      }
    }
  return result.reverse();
};
// @openarc:end flattenArray.flatten

export type OfSizeFn = (size: number) => number[][];

export const ofSizeSpec = arc.defineRegion<OfSizeFn>({
  "id": "spiralMatrix.ofSize",
  "intent": [
    "Exercise \"spiral-matrix\": implement `ofSize`.",
    "Your task is to return a square matrix of a given size.",
    "The matrix should be filled with natural numbers, starting from 1 in the top-left corner, increasing in an inward, clockwise spiral order, like these examples:",
    "## Examples",
    "### Spiral matrix of size 3",
    "```text 1 2 3 8 9 4 7 6 5 ```",
    "### Spiral matrix of size 4",
    "```text 1  2  3 4 12 13 14 5 11 16 15 6 10  9  8 7 ```"
  ],
  "examples": [
    {
      "name": "Spiral Matrix > empty spiral",
      "args": [
        0
      ],
      "expected": []
    },
    {
      "name": "Spiral Matrix > trivial spiral",
      "args": [
        1
      ],
      "expected": [
        [
          1
        ]
      ]
    }
  ]
});

// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  if (size <= 0) {
      return [];
    }
  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
  let num = 1;
  let top = 0, bottom = size - 1, left = 0, right = size - 1;
  while (top <= bottom && left <= right) {
      for (let i = left; i <= right; i++) {
        matrix[top][i] = num++;
      }
      top++;

      for (let i = top; i <= bottom; i++) {
        matrix[i][right] = num++;
      }
      right--;

      if (top <= bottom) {
        for (let i = right; i >= left; i--) {
          matrix[bottom][i] = num++;
        }
        bottom--;
      }

      if (left <= right) {
        for (let i = bottom; i >= top; i--) {
          matrix[i][left] = num++;
        }
        left++;
      }
    }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

