export type FindFn = (haystack: number[], needle: number) => number;

export const findSpec = arc.defineRegion<FindFn>({
  "id": "binarySearch.find",
  "intent": [
    "Exercise \"binary-search\": implement `find`.",
    "Your task is to implement a binary search algorithm.",
    "A binary search algorithm finds an item in a list by repeatedly splitting it in half, only keeping the half which contains the item we're looking for. It allows us to quickly narrow down the possible locations of our item until we find it, or until we've eliminated all possible locations.",
    "~~~~exercism/caution Binary search only works when a list has been sorted. ~~~~",
    "The algorithm looks like this:",
    "- Find the middle element of a _sorted_ list and compare it with the item we're looking for. - If the middle element is our item, then we're done! - If the middle element is greater than our item, we can eliminate that element and all the elements **after** it. - If the middle element is less than our item, we can eliminate that element and all the elements **before** it. - If every element of the list has been eliminated then the item is not in the list. - Otherwise, repeat the process on the part of the list that has not been eliminated.",
    "Here's an example:",
    "Let's say we're looking for the number 23 in the following sorted list: `[4, 8, 12, 16, 23, 28, 32]`.",
    "- We start by comparing 23 with the middle element, 16. - Since 23 is greater than 16, we can eliminate the left half of the list, leaving us with `[23, 28, 32]`. - We then compare 23 with the new middle element, 28. - Since 23 is less than 28, we can eliminate the right half of the list: `[23]`. - We've found our item."
  ],
  "examples": [
    {
      "name": "Binary Search > finds a value in an array with one element",
      "args": [
        [
          6
        ],
        6
      ],
      "expected": 0
    },
    {
      "name": "Binary Search > finds a value in the middle of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        6
      ],
      "expected": 3
    },
    {
      "name": "Binary Search > finds a value at the beginning of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        1
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      if (haystack[mid] === needle) {
        return mid;
      } else if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
// @openarc:end binarySearch.find

