  while (top <= bottom && left <= right) {
      for (let i = left; i <= right; i++) {
        matrix[top][i] = num++;
      }
      top++;

      for (let i = top; i <= bottom; i++) {
        matrix[i][right] = num++;
      }
      right--;

      if (top <= bottom) {
        for (let i = right; i >= left; i--) {
          matrix[bottom][i] = num++;
        }
        bottom--;
      }

      if (left <= right) {
        for (let i = bottom; i >= top; i--) {
          matrix[i][left] = num++;
        }
        left++;
      }
    }
  return matrix;
};
