// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  if (rows.length === 0) return [];
  const maxLength = Math.max(...rows.map(row => row.length));
  const transposed: string[] = [];
  for (let col = 0; col < maxLength; col++) {
      let newRow = '';
      for (let row of rows) {
        newRow += col < row.length ? row[col] : ' ';
      }
      transposed.push(newRow);
    }
  return transposed;
};
// @openarc:end transpose.transpose

// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (haystack[mid] === needle) {
      return mid;
    } else if (haystack[mid] < needle) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return -1;
};
// @openarc:end binarySearch.find

// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  const stack: (number | null | undefined | Nested)[] = [...input];
  while (stack.length > 0) {
      const current = stack.pop();
      if (Array.isArray(current)) {
        stack.push(...current);
      } else if (current !== null && current !== undefined) {
        result.push(current);
      }
    }
  return result.reverse();
};
// @openarc:end flattenArray.flatten

// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  // hand-written: fill ring by ring
  const m: number[][] = Array.from({ length: size }, () => new Array<number>(size).fill(0));
  let n = 1;
  for (let ring = 0; ring < Math.ceil(size / 2); ring++) {
    const last = size - 1 - ring;
    for (let c = ring; c <= last; c++) m[ring]![c] = n++;
    for (let r = ring + 1; r <= last; r++) m[r]![last] = n++;
    for (let c = last - 1; c >= ring && last > ring; c--) m[last]![c] = n++;
    for (let r = last - 1; r > ring && last > ring; r--) m[r]![ring] = n++;
  }
  return m;
};
// @openarc:end spiralMatrix.ofSize

